*/
   sprintf( filename, "%s%04u.glb", prefix, filenum );
   if ( ( handle = open( filename, permissions ) ) == -1 )
	{
      sprintf( filename, "%s%s%04u.glb", exePath, prefix, filenum );
   	if ( ( handle = open( filename, permissions ) ) == -1 )
