   {
      tileloopy = SCREENHEIGHT - y;
      flag = TRUE;
   }
  
   tilestart = displaybuffer + x + ylookup [ y ];
  
   if ( flag )
      TILE_ClipDraw();
   else
      TILE_Draw();
}
  
