TILE_FreeLevel (
VOID
)
{
   INT      loop;

   for ( loop = 0; loop < MAP_SIZE; loop++ )
   {
      GLB_FreeItem ( titems [ loop ] );

      if ( eitems [ loop ] !=  titems [ loop ] )
         GLB_FreeItem ( eitems [ loop ] );
   }
}

